package main

import (
	"fmt"
	"strings"
)

func Reverse(s string) string {
	runes := []rune(s)
	for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
		runes[i], runes[j] = runes[j], runes[i]
	}
	return string(runes)
}

func CountWords(s string) map[string]int {
	counts := make(map[string]int)
	words := strings.Field(s)
	for _, w := range words {
		counts[strings.ToLower(w)]++
	}
	return counts
}

func IsPalindrome(s string) bool {
	cleaned := strings.ToLower(s)
	return cleaned == Reverse(cleaned)
}

func main() {
	fmt.Println("App ready")
}

package main

import "testing"

func TestReverse(t *testing.T) {
	if got := Reverse("hello"); got != "olleh" {
		t.Errorf("Reverse(hello) = %s, want olleh", got)
	}
	if got := Reverse(""); got != "" {
		t.Errorf("Reverse('') = %s, want ''", got)
	}
}

func TestCountWords(t *testing.T) {
	counts := CountWords("hello world hello")
	if counts["hello"] != 2 {
		t.Errorf("hello count = %d, want 2", counts["hello"])
	}
	if counts["world"] != 1 {
		t.Errorf("world count = %d, want 1", counts["world"])
	}
}

func TestIsPalindrome(t *testing.T) {
	if !IsPalindrome("racecar") {
		t.Error("racecar should be a palindrome")
	}
	if IsPalindrome("hello") {
		t.Error("hello should not be a palindrome")
	}
}

